test("durable snapshots restore a structurally complete pending permission", () => {
  useSessionStore.getState().restore({
    ...snapshot(2, 1),
    running: true,
    activeRunId: "run-1",
    activeRunRevision: 4,
    permission: {
      status: "pending",
      permissionId: "permission-1",
      revision: 3,
      toolName: "shell",
      arguments: { command: "git status" },
      workspace: { workspaceId: "workspace-1", generation: 4 },
      risk: { level: "high", ruleId: "workspace-default" },
    },
  })

  expect(useSessionStore.getState().permission).toEqual({
    id: "permission-1",
    tool: "shell",
    arguments: { command: "git status" },
    workspace: { workspaceId: "workspace-1", generation: 4 },
    risk: { level: "high", ruleId: "workspace-default" },
    revision: 3,
  })
})

test("snapshot permission recovery fails closed for non-pending or incomplete projections", () => {
  const complete = {
    status: "pending" as const,
    permissionId: "permission-1",
    revision: 3,
    toolName: "shell",
    arguments: { command: "git status" },
    workspace: { workspaceId: "workspace-1", generation: 4 },
    risk: { level: "high" as const, ruleId: "workspace-default" },
  }
  useSessionStore.getState().restore({ ...snapshot(2, 1), permission: { ...complete, status: "allowed" } })
  expect(useSessionStore.getState().permission).toBeNull()

  useSessionStore.getState().restore({
    ...snapshot(3, 2),
    permission: { ...complete, workspace: { workspaceId: "", generation: 4 } },
  })
  expect(useSessionStore.getState().permission).toBeNull()
})

